//
// osk.sv - on-screen keyboard for handheld play (no Dock keyboard)
//
// osk_ctrl turns pad 1 into keyboard navigation while the keyboard is shown;
// osk_overlay draws it over the video stream going to the APF scaler.
// Layout and font are generated by tools/gen_osk.py; see docs/input.md.
//

`default_nettype none

module osk_ctrl (
	input  wire        clk,          // clk_32
	input  wire        reset,
	input  wire [15:0] pad,          // cont1_key[15:0]

	output reg         visible,
	output reg   [2:0] cur_row,
	output reg   [3:0] cur_col,
	output reg   [2:0] mods,         // latched {alt, shift, ctrl}
	output reg   [7:0] key,          // HID usage held down, 0 = none
	output reg         mouse_toggle  // Start pressed with the keyboard hidden
);

`include "osk_layout.svh"

localparam ROWS = 5, COLS = 16;
localparam [23:0] REPEAT_FIRST = 24'd12_800_000;  // ~400 ms at 32 MHz
localparam [23:0] REPEAT_NEXT  = 24'd3_200_000;   // ~100 ms

wire up = pad[0], down = pad[1], left = pad[2], right = pad[3];
wire btn_a = pad[4], btn_b = pad[5], select = pad[14], start = pad[15];

reg  [15:0] pad_d;
reg  [23:0] repeat_cnt;
wire [3:0]  dir = pad[3:0];
wire        dir_edge = |(pad[3:0] & ~pad_d[3:0]);
wire [7:0]  usage = osk_usage(cur_row, cur_col);
wire        usage_is_mod = usage == 8'hE0 || usage == 8'hE1 || usage == 8'hE2 || usage == 8'hE5;

initial begin
	visible = 1'b0; cur_row = 3'd0; cur_col = 4'd0; mods = 3'b000; key = 8'h00; mouse_toggle = 1'b0;
end

always @(posedge clk) begin
	reg step;
	pad_d <= pad;
	mouse_toggle <= 1'b0;

	if (reset) begin
		visible <= 1'b0;
		mods <= 3'b000;
		key <= 8'h00;
	end else begin
		if (select & ~pad_d[14]) begin
			visible <= ~visible;
			key <= 8'h00;
		end
		if (start & ~pad_d[15] & ~visible) mouse_toggle <= 1'b1;

		if (visible) begin
			// D-pad with auto-repeat
			step = 1'b0;
			if (dir == 4'd0) repeat_cnt <= 24'd0;
			else if (dir_edge) begin step = 1'b1; repeat_cnt <= REPEAT_FIRST; end
			else if (repeat_cnt == 24'd0) begin step = 1'b1; repeat_cnt <= REPEAT_NEXT; end
			else repeat_cnt <= repeat_cnt - 24'd1;

			if (step && key == 8'h00) begin
				if (up)    cur_row <= (cur_row == 0) ? 3'(ROWS - 1) : cur_row - 3'd1;
				if (down)  cur_row <= (cur_row == 3'(ROWS - 1)) ? 3'd0 : cur_row + 3'd1;
				if (left)  cur_col <= cur_col - 4'd1;   // 16 columns: wraps naturally
				if (right) cur_col <= cur_col + 4'd1;
			end

			// A: modifiers latch until the next key is released; other keys are held while A is
			if (btn_a & ~pad_d[4]) begin
				if (usage_is_mod) begin
					if (usage == 8'hE0) mods[0] <= ~mods[0];
					if (usage == 8'hE1 || usage == 8'hE5) mods[1] <= ~mods[1];
					if (usage == 8'hE2) mods[2] <= ~mods[2];
				end else
					key <= usage;
			end
			if (~btn_a & pad_d[4] & (key != 8'h00)) begin
				key <= 8'h00;
				mods <= 3'b000;
			end

			// B closes the keyboard
			if (btn_b & ~pad_d[5]) begin
				visible <= 1'b0;
				key <= 8'h00;
			end
		end
	end
end

endmodule


module osk_overlay #(
	parameter FONT_FILE = "core/osk_font.hex"
) (
	input  wire        clk,
	input  wire        visible,
	input  wire  [2:0] cur_row,
	input  wire  [3:0] cur_col,
	input  wire  [2:0] mods,
	input  wire        badge,        // show the pad-mode label
	input  wire        badge_mouse,  // 1: "MOUSE", 0: "JOYSTICK"

	input  wire [23:0] in_rgb,
	input  wire        in_de,
	input  wire        in_skip,
	input  wire        in_hs,
	input  wire        in_vs,

	// same stream, 2 clocks later
	output reg  [23:0] video_rgb,
	output reg         video_de,
	output reg         video_skip,
	output reg         video_hs,
	output reg         video_vs
);

`include "osk_layout.svh"

localparam KB_W = 640, KB_H = 80, CELL_W = 40, CELL_H = 16;

reg [7:0] font[1024];
initial $readmemh(FONT_FILE, font);

// geometry of the incoming picture, measured from the previous line / frame
reg  [9:0] px, py, width, height;
reg        de_d;

always @(posedge clk) begin
	de_d <= in_de;
	if (in_de && !in_skip) px <= px + 10'd1;
	if (de_d && !in_de) begin
		width <= px;
		px <= 10'd0;
		py <= py + 10'd1;
	end
	if (in_vs) begin
		height <= py;
		py <= 10'd0;
	end
end

// stage 0: keyboard-relative position
wire [9:0]  kx = px - ((width - 10'(KB_W)) >> 1);
wire [9:0]  ky = py - (height - 10'(KB_H) - 10'd4);
wire        in_kb = visible && in_de && (kx < 10'(KB_W)) && (ky < 10'(KB_H)) && (width >= 10'(KB_W)) && (height > 10'(KB_H + 4));
// kx / 40 for kx < 640, exact over that range
wire [16:0] col_mul = kx * 17'd205;
wire [3:0]  col = col_mul[16:13];
wire [5:0]  cx = 6'(kx - col * 10'(CELL_W));
wire [2:0]  row = ky[6:4];
wire [3:0]  cy = ky[3:0];
wire [5:0]  tx = cx - 6'd4;          // 4 label characters start 4 pixels into the cell
wire [3:0]  ty = cy - 4'd4;
wire        text_area = (cx >= 6'd4) && (cx < 6'd36) && (cy >= 4'd4) && (cy < 4'd12);
wire [7:0]  cell_usage = osk_usage(row, col);
wire        latched = (cell_usage == 8'hE0 && mods[0]) || ((cell_usage == 8'hE1 || cell_usage == 8'hE5) && mods[1]) ||
                      (cell_usage == 8'hE2 && mods[2]);

// pad-mode label, top left: 8 characters at x 8-71, y 4-11 (keyboard is at the bottom)
wire [9:0]  bx = px - 10'd8;
wire [9:0]  by = py - 10'd4;
wire        in_badge = badge && in_de && (bx < 10'd64) && (by < 10'd8);
function automatic [6:0] badge_char(input mouse, input [2:0] pos);
	case ({mouse, pos})
		4'h0: badge_char = 7'd74; 4'h1: badge_char = 7'd79; 4'h2: badge_char = 7'd89; 4'h3: badge_char = 7'd83;  // JOYS
		4'h4: badge_char = 7'd84; 4'h5: badge_char = 7'd73; 4'h6: badge_char = 7'd67; 4'h7: badge_char = 7'd75;  // TICK
		4'h8: badge_char = 7'd32; 4'h9: badge_char = 7'd77; 4'hA: badge_char = 7'd79; 4'hB: badge_char = 7'd85;  //  MOU
		4'hC: badge_char = 7'd83; 4'hD: badge_char = 7'd69; default: badge_char = 7'd32;                          // SE
	endcase
endfunction

// stage 1: glyph row lookup
reg  [7:0]  glyph;
reg  [2:0]  bit_s1;
reg         in_kb_s1, badge_s1, text_s1, edge_s1, cursor_s1, latched_s1;
reg [23:0]  rgb_s1;
reg         de_s1, skip_s1, hs_s1, vs_s1;

always @(posedge clk) begin
	glyph      <= in_badge ? font[{badge_char(badge_mouse, bx[5:3]), by[2:0]}]
	                       : font[{osk_char(row, col, tx[4:3]), ty[2:0]}];
	bit_s1     <= in_badge ? bx[2:0] : tx[2:0];
	in_kb_s1   <= in_kb | in_badge;
	badge_s1   <= in_badge;
	text_s1    <= text_area;
	edge_s1    <= (cx == 6'd0) || (cy == 4'd0) || (cx == 6'(CELL_W - 1));
	cursor_s1  <= (row == cur_row) && (col == cur_col);
	latched_s1 <= latched;
	{rgb_s1, de_s1, skip_s1, hs_s1, vs_s1} <= {in_rgb, in_de, in_skip, in_hs, in_vs};
end

// stage 2: compose
always @(posedge clk) begin
	reg ink;
	ink = text_s1 && glyph[bit_s1];
	{video_de, video_skip, video_hs, video_vs} <= {de_s1, skip_s1, hs_s1, vs_s1};
	if (!in_kb_s1)      video_rgb <= rgb_s1;
	else if (badge_s1)  video_rgb <= glyph[bit_s1] ? 24'hFFFFFF : 24'h203060;
	else if (edge_s1)   video_rgb <= 24'h181820;
	else if (cursor_s1) video_rgb <= ink ? 24'h000000 : 24'hF0F0F0;
	else if (latched_s1) video_rgb <= ink ? 24'h000000 : 24'hE0A000;
	else                video_rgb <= ink ? 24'hFFFFFF : 24'h505868;
end

endmodule

`default_nettype wire
